private void validateRegisterRequest(RegisterArtifactRequest request) {
    if (request.name() == null || request.name().isBlank()) {
        throw ApiException.badRequest("name 不能为空");
    }
    List<DependencySpec> deps = request.dependencies();
    if (deps.size() > 10) {
