        assertThat(result.versions()).isEqualTo(Map.of("root", 1, "a", 1, "c", 1));
        assertThat(result.edges()).containsExactly(
                new KeptEdge("root", 1, "a", 1),
                new KeptEdge("root", 1, "c", 1));
    }
}

