                "c", List.of(v(1)));

        assertThat(LockResolver.resolve(s, "root", 1))
                .isEqualTo(Map.of("root", 1, "a", 1));
    }

    @Test
    void cycleEdgeCanBeExcluded() {
        // a -> b（排除 c）；b -> c；c -> a。排除 c 后环被剪断，c 不进入解。
        RepositorySnapshot s = snapshot(0,
